function sgEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function sgColor(c){ var s=String(c||'').trim(); return /^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(s) ? s : '#5E6AD2'; }
function sgInitials(name){ var parts=String(name||'').trim().split(/\s+/).filter(Boolean); if(!parts.length) return '?'; var a=parts[0][0]||'', b=parts.length>1?(parts[parts.length-1][0]||''):''; return (a+b).toUpperCase(); }
function sgUrlLabel(url){ return String(url||'').replace(/^https?:\/\//,'').replace(/\/$/,''); }
function sgBuild(d){
  d=d||{};
  var accent=sgColor(d.accent);
  var rows=[];
  if(d.phone) rows.push('<span style="color:#6b7280;">Tel</span>&nbsp; '+sgEsc(d.phone));
  if(d.email) rows.push('<span style="color:#6b7280;">Mail</span>&nbsp; <a href="mailto:'+sgEsc(d.email)+'" style="color:'+accent+';text-decoration:none;">'+sgEsc(d.email)+'</a>');
  if(d.site) rows.push('<span style="color:#6b7280;">Web</span>&nbsp; <a href="'+sgEsc(d.site)+'" style="color:'+accent+';text-decoration:none;">'+sgEsc(sgUrlLabel(d.site))+'</a>');
  var contact=rows.map(function(r){ return '<div style="margin:2px 0;">'+r+'</div>'; }).join('');
  return '<table cellpadding="0" cellspacing="0" border="0" style="font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#111827;">'
    +'<tr>'
    +'<td style="padding-right:14px;vertical-align:top;">'
    +'<table cellpadding="0" cellspacing="0" border="0"><tr><td width="52" height="52" align="center" style="background:'+accent+';border-radius:26px;color:#ffffff;font-size:18px;font-weight:bold;">'+sgEsc(sgInitials(d.name))+'</td></tr></table>'
    +'</td>'
    +'<td style="border-left:2px solid '+accent+';padding-left:14px;vertical-align:top;">'
    +'<div style="font-size:15px;font-weight:bold;color:#111827;">'+sgEsc(d.name||'')+'</div>'
    +'<div style="color:#6b7280;margin:2px 0 6px;">'+sgEsc(d.title||'')+(d.title&&d.company?' · ':'')+sgEsc(d.company||'')+'</div>'
    +contact
    +'</td>'
    +'</tr></table>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { sgEsc:sgEsc, sgColor:sgColor, sgInitials:sgInitials, sgUrlLabel:sgUrlLabel, sgBuild:sgBuild };
}
if (typeof window !== 'undefined') {
  window.SigForgePure = { sgEsc:sgEsc, sgColor:sgColor, sgInitials:sgInitials, sgUrlLabel:sgUrlLabel, sgBuild:sgBuild };
}
